<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';
$user=app_require_auth();
$canSelf=app_has_permission('employee.self',$user)||app_has_permission('schedule.self',$user)||app_has_permission('timeclock.self',$user)||app_has_permission('training.self_view',$user)||app_has_permission('tasks.self',$user)||app_has_permission('agent.employee_view',$user);
$canManage=app_has_permission('employee.manage',$user)||app_has_permission('staff.manage',$user);
$canAnnouncements=app_has_permission('employee.announcements.manage',$user);$canPolicies=app_has_permission('employee.policies.manage',$user);
$canHandoffsView=app_has_permission('employee.handoffs.view',$user)||$canSelf||$canManage;$canHandoffsCreate=app_has_permission('employee.handoffs.create',$user)||$canManage;$canHandoffsManage=app_has_permission('employee.handoffs.manage',$user)||$canManage;
